class Document:
    def __init__(self, path: str) -> None:
        self._stack = contextlib.ExitStack()
        self._file = self._stack.enter_context(open(path, "w+"))  # owned resource
        self._parts: list[Paragraph] = []
    def add(self, text: str) -> Paragraph:
        part = Paragraph(text); part.owner = weakref.ref(self)    # non-owning back-ref
        self._parts.append(part); return part
    def close(self) -> None:                                      # cascades to parts
        for part in self._parts: part.close()
        self._stack.close()
